import { SPACES, MENU_ITEMS, spaceById } from "../../data/catalog.js";
import { ReservationStep } from "../../domain/reservation.js";
import { escapeHtml } from "../dom.js";

function stepper(step){return '<div class="stepper">'+[0,1,2,3].map(i=>'<span class="'+(i<=step?"on":"")+'"></span>').join("")+'</div>';}
function field(label,name,value,type,errorText){
  return '<div class="field"><label>'+escapeHtml(label)+'</label><input data-field="'+name+'" type="'+type+'" value="'+escapeHtml(value??"")+'">'+(errorText?'<span class="error">'+escapeHtml(errorText)+'</span>':"")+'</div>';
}

export function renderReserve(state,{t,tr}){
  const d=state.reservationDraft;
  const errors=state.reservationErrors||{};
  const required=t("reserve.required");
  let body="";
  if(state.reservationStep===ReservationStep.DETAILS){
    body=['<div class="panel form-grid">',
      field(t("reserve.date"),"date",d.date,"date",errors.date?required:""),
      field(t("reserve.time"),"time",d.time,"time",""),
      field(t("reserve.guests"),"guests",d.guests,"number",""),
      field(t("reserve.occasion"),"occasion",d.occasion,"text",""),
      field(t("reserve.name"),"name",d.name,"text",errors.name?required:""),
      field(t("reserve.phone"),"phone",d.phone,"tel",errors.phone?required:""),
      field(t("reserve.email"),"email",d.email,"email",""),
      '<button class="btn full" data-action="reserve-next-details">'+escapeHtml(t("common.continue"))+'</button></div>'
    ].join("");
  } else if(state.reservationStep===ReservationStep.SPACE){
    const options=SPACES.map(space=>'<button class="space-option '+(state.selectedAreaId===space.id?"selected":"")+'" data-action="select-reserve-space" data-id="'+space.id+'"><img src="'+space.image+'" alt=""><span><strong>'+escapeHtml(tr(space.title))+'</strong><span class="muted">'+escapeHtml(tr(space.text))+'</span></span></button>').join("");
    body='<h2 class="section-title">'+escapeHtml(t("reserve.chooseSpace"))+'</h2>'+(errors.space?'<p class="error">'+escapeHtml(required)+'</p>':"")+options+'<div class="actions"><button class="btn secondary" data-action="reserve-back">'+escapeHtml(t("common.back"))+'</button><button class="btn" data-action="reserve-next-space">'+escapeHtml(t("common.continue"))+'</button></div>';
  } else if(state.reservationStep===ReservationStep.REVIEW){
    const space=spaceById(state.selectedAreaId);
    const prefs=state.selectedMenuIds.map(id=>MENU_ITEMS.find(item=>item.id===id)).filter(Boolean).map(item=>escapeHtml(tr(item.title))).join(", ");
    body='<div class="panel summary-list"><div class="summary-row"><span>'+escapeHtml(t("reserve.space"))+'</span><strong>'+escapeHtml(space?tr(space.title):"—")+'</strong></div><div class="summary-row"><span>'+escapeHtml(t("reserve.date"))+'</span><strong>'+escapeHtml(d.date||"—")+'</strong></div><div class="summary-row"><span>'+escapeHtml(t("reserve.time"))+'</span><strong>'+escapeHtml(d.time||"—")+'</strong></div><div class="summary-row"><span>'+escapeHtml(t("reserve.guests"))+'</span><strong>'+escapeHtml(String(d.guests||"—"))+'</strong></div><div class="summary-row"><span>Menu</span><strong>'+(prefs||"—")+'</strong></div></div><div class="actions"><button class="btn secondary" data-action="reserve-back">'+escapeHtml(t("common.back"))+'</button><button class="btn" data-action="reserve-next-review">'+escapeHtml(t("reserve.secure"))+'</button></div>';
  } else if(state.reservationStep===ReservationStep.DEPOSIT){
    body='<div class="panel"><div class="kicker">500,000 VND</div><h2 class="section-title">'+escapeHtml(t("reserve.payment"))+'</h2><p class="muted">'+escapeHtml(t("reserve.requestOnly"))+'</p><div class="actions"><button class="btn secondary" data-action="reserve-back">'+escapeHtml(t("common.back"))+'</button><button class="btn" data-action="reserve-confirm">'+escapeHtml(t("reserve.submit"))+'</button></div></div>';
  } else {
    body='<div class="panel"><div class="kicker">LUME</div><h2 class="section-title">'+escapeHtml(t("reserve.confirmed"))+'</h2><button class="btn" data-action="tab" data-tab="guest">'+escapeHtml(t("nav.guest"))+'</button></div>';
  }
  return '<section class="section"><div class="kicker">LUME</div><h1 class="section-title">'+escapeHtml(t("reserve.title"))+'</h1><p class="muted">'+escapeHtml(t("reserve.hint"))+'</p>'+stepper(state.reservationStep)+'</section>'+body;
}

