  {id:"celebration",title:"Celebration menu",price:"from 4,500,000 VND",note:"custom courses, wine and dessert"}
]);

const AREA_IDS=new Set(["dining","garden","bar","rooftop"]);
const EXPERIENCE_IDS=new Set(["romantic","sunset","family","private"]);
const MENU_IDS=new Set(MENU.map(item=>item.id));

export const menuIds=()=>Array.from(MENU_IDS);

export function cleanText(value,max=1200){
  return String(value==null?"":value).replace(/\0/g,"").trim().slice(0,max);
}

export function safeHistory(value){
  if(!Array.isArray(value)) return [];
  return value.slice(-8)
    .map(entry=>({role:entry?.role==="assistant"?"assistant":"user",content:cleanText(entry?.content,800)}))
    .filter(entry=>Boolean(entry.content));
}

export function normalizePlan(plan){
  if(!plan||typeof plan!=="object") return null;
  const areaId=AREA_IDS.has(plan.areaId)?plan.areaId:null;
  const experienceId=EXPERIENCE_IDS.has(plan.experienceId)?plan.experienceId:null;
  const menuItemIds=Array.isArray(plan.menuItemIds)?plan.menuItemIds.filter(id=>MENU_IDS.has(id)).slice(0,5):[];
  const guests=Number.isFinite(Number(plan.guests))?Math.min(50,Math.max(1,Number(plan.guests))):null;
  const time=/^(1[7-9]|20):[0-5]\d$/.test(String(plan.time||""))?String(plan.time):null;
  if(!areaId&&!experienceId&&!menuItemIds.length&&!plan.title) return null;
  return {
    title:cleanText(plan.title,100),
    areaId,
    experienceId,
    time,
    guests,
    mood:cleanText(plan.mood,140),
    pairing:cleanText(plan.pairing,180),
    reason:cleanText(plan.reason,280),
    menuItemIds
  };
}

export function buildPrompt({message,lang,history,context}){
  const language=lang==="ru"?"Russian":lang==="vi"?"Vietnamese":"English";
  const menu=MENU.map(item=>item.id+": "+item.title+" — "+item.price+"; "+item.note).join("\n");
