import { MODEL } from "./domain.js";
import { handleConcierge } from "./concierge.js";

function json(data,status=200){
  return new Response(JSON.stringify(data),{
    status,
    headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}
  });
}

export default {
  async fetch(request,env){
    const url=new URL(request.url);
    if(url.pathname==="/api/health"){
      return json({ok:true,service:"lume-mini-app-v2",aiBinding:Boolean(env.AI),model:MODEL});
    }
    if(url.pathname==="/api/concierge"){
      if(request.method!=="POST") return json({error:"method_not_allowed"},405);
      return handleConcierge(request,env);
    }
    return env.ASSETS.fetch(request);
  }
};
